def _forward_args(ctx: typer.Context, command_name: str) -> list[str]:
    """Extract arguments passed to the specific subcommand from ctx.args or sys.argv."""
    if ctx.args:
        return list(ctx.args)
    argv = sys.argv[1:]
    try:
        idx = argv.index(command_name)
        return argv[idx + 1 :]
    except ValueError:
        return []

