def _load_gitignore_spec(root: Path) -> pathspec.PathSpec | None:
    gitignore_path = root / ".gitignore"
    if not gitignore_path.is_file():
        return None
    try:
        lines = gitignore_path.read_text(
            encoding="utf-8", errors="replace"
        ).splitlines()
    except OSError:
        return None
    return pathspec.PathSpec.from_lines("gitignore", lines)

def walk(
    root: Path,
    *,
    max_file_size: int = 2_000_000,
    available_languages: set[str] | None = None,
) -> WalkResult:
    """Walk `root`, returning files whose extension maps to a known language.

    `available_languages` restricts which detected languages are actually
    included (grammars that failed to load are counted, not walked into
    the parse stage).
    """
    gitignore_spec = _load_gitignore_spec(root)
    files: list[DiscoveredFile] = []
    directories: set[str] = set()
    skipped_too_large: list[str] = []
    skipped_unsupported_grammar: dict[str, int] = {}

    for dirpath, dirnames, filenames in os.walk(root):
        dirnames.sort()
        dirnames[:] = [d for d in dirnames if d not in DEFAULT_EXCLUDED_DIRS]
        current_dir = Path(dirpath)

        if gitignore_spec is not None:
            pruned = []
            for d in dirnames:
                rel = (current_dir / d).relative_to(root).as_posix()
                if gitignore_spec.match_file(rel + "/"):
                    continue
                pruned.append(d)
            dirnames[:] = pruned

        for filename in sorted(filenames):
            abs_path = current_dir / filename
            rel_path = abs_path.relative_to(root).as_posix()

            if gitignore_spec is not None and gitignore_spec.match_file(rel_path):
                continue

            ext = abs_path.suffix.lower()
            language = EXTENSION_TO_LANGUAGE.get(ext)
            if language is None:
                continue

            if available_languages is not None and language not in available_languages:
                skipped_unsupported_grammar[language] = (
                    skipped_unsupported_grammar.get(language, 0) + 1
                )
                continue

            try:
                size = abs_path.stat().st_size
            except OSError:
                continue
            if size > max_file_size:
                skipped_too_large.append(rel_path)
                continue

            files.append(
                DiscoveredFile(abs_path=abs_path, rel_path=rel_path, language=language)
            )
            parent = Path(rel_path).parent.as_posix()
            while parent and parent != ".":
                directories.add(parent)
                parent = Path(parent).parent.as_posix()

    files.sort(key=lambda f: f.rel_path)
    return WalkResult(
        files=files,
        directories=directories,
        skipped_too_large=skipped_too_large,
        skipped_unsupported_grammar=skipped_unsupported_grammar,
    )

def read_existing_content_hash(doc_abs_path: Path) -> str | None:
    """Extract `sources[0].content_hash` from an existing OKF doc's frontmatter, if any."""
    if not doc_abs_path.is_file():
        return None
    try:
        text = doc_abs_path.read_text(encoding="utf-8")
    except OSError:
        return None

    match = _FRONTMATTER_RE.match(text)
    frontmatter = match.group(1) if match else text
    hash_match = _CONTENT_HASH_RE.search(frontmatter)
    return hash_match.group(1) if hash_match else None

def topological_doc_order(graph: CodeGraph) -> list[GraphNode]:
    """Return clusterable nodes ordered so every callee/base precedes its callers.

    Cycles (mutual/recursive calls) can't be strictly ordered; nodes involved
    in a cycle are appended in a stable (id-sorted) order once every node
    outside the cycle that can be resolved has been. This never raises on
    cyclic graphs.
    """
    nodes = {n.id: n for n in graph.nodes.values() if n.kind in _CLUSTERABLE_KINDS}
    if not nodes:
        return []

    # dependency edges: source depends on target (target must be documented first)
    depends_on: dict[str, set[str]] = {node_id: set() for node_id in nodes}
    dependents: dict[str, set[str]] = {node_id: set() for node_id in nodes}
    for edge in graph.edges:
        if edge.kind not in _ORDER_EDGE_KINDS:
            continue
        if edge.source not in nodes or edge.target not in nodes:
            continue
        if edge.source == edge.target:
            continue
        depends_on[edge.source].add(edge.target)
        dependents[edge.target].add(edge.source)

    remaining_deps = {node_id: set(deps) for node_id, deps in depends_on.items()}
    ready = sorted(node_id for node_id, deps in remaining_deps.items() if not deps)
    ordered: list[str] = []
    seen: set[str] = set()

    while ready:
        ready.sort()
        node_id = ready.pop(0)
        if node_id in seen:
            continue
        seen.add(node_id)
        ordered.append(node_id)
        for dependent in sorted(dependents.get(node_id, ())):
            if dependent in seen:
                continue
            remaining_deps[dependent].discard(node_id)
            if not remaining_deps[dependent]:
                ready.append(dependent)

    # Anything left is part of a cycle; append deterministically.
    leftover = sorted(node_id for node_id in nodes if node_id not in seen)
    ordered.extend(leftover)

    return [nodes[node_id] for node_id in ordered]

def classify_doc_section(rel_path: Path) -> str:
    """Classify relative document path into a human-friendly documentation section."""
    parts = rel_path.parts
    if len(parts) <= 1:
        return "Overview"
    top = parts[0]
    if top in ("communities", "god-nodes"):
        return top
    if top == "src" and len(parts) >= 3:
        return parts[2].replace("_", " ").title()
    if top == ".agents":
        return "Harness & Skills"
    if top == "tests":
        return "Tests"
    return top.replace("_", " ").title()

def get_theme_dir() -> Path:
