def _resolve_js_import(imp: PendingImport, file_paths: set[str | None]) -> str | None:
    text = imp.path_text
    if not text.startswith("."):
        return None
    importing_dir = PurePosixPath(imp.importing_file_rel).parent
    base = (importing_dir / text).as_posix()
    base = str(PurePosixPath(base))

    candidates = [base] if PurePosixPath(base).suffix else []
    for suffix in _JS_SUFFIXES:
        candidates.append(f"{base}{suffix}")
    for suffix in _JS_SUFFIXES:
        candidates.append(f"{base}/index{suffix}")

    return _candidate_exists(file_paths, *candidates)

def _resolve_python_import(
    imp: PendingImport, file_paths: set[str | None]
) -> str | None:
    text = imp.path_text
    importing_dir = PurePosixPath(imp.importing_file_rel).parent

    if text.startswith("."):
        dots = len(text) - len(text.lstrip("."))
        remainder = text[dots:]
        base = importing_dir
        for _ in range(dots - 1):
            base = base.parent
        module_path = base / remainder.replace(".", "/") if remainder else base
    else:
        module_path = PurePosixPath(text.replace(".", "/"))

    return _candidate_exists(
        file_paths,
        f"{module_path}.py",
        f"{module_path}/__init__.py",
    )

def _resolve_rust_import(imp: PendingImport, file_paths: set[str | None]) -> str | None:
    text = imp.path_text
    importing_dir = PurePosixPath(imp.importing_file_rel).parent

    if text.startswith("crate::") or text == "crate":
        remainder = text[len("crate::") :] if text != "crate" else ""
        base = (
            PurePosixPath("src") / remainder.replace("::", "/")
            if remainder
            else PurePosixPath("src/lib")
        )
    elif text.startswith("self::"):
        remainder = text[len("self::") :]
        base = importing_dir / remainder.replace("::", "/")
    elif text.startswith("super::"):
        remainder = text[len("super::") :]
        base = importing_dir.parent / remainder.replace("::", "/")
    else:
        return None

    return _candidate_exists(file_paths, f"{base}.rs", f"{base}/mod.rs")

def resolve(ctx: BuildContext) -> None:
    file_paths = {
        node.file_path for node in ctx.graph.nodes.values() if node.kind == FILE
    }

    file_exports: dict[str, dict[str, str]] = {}
    global_symbols: dict[str, list[str]] = {}
    class_methods: dict[str, dict[str, str]] = {}

    for node in ctx.graph.nodes.values():
        if node.file_path and node.kind in (FUNCTION, METHOD, CLASS):
            file_exports.setdefault(node.file_path, {})[node.name] = node.id
            global_symbols.setdefault(node.name, []).append(node.id)
            if node.qualified_name != node.name:
                file_exports[node.file_path][node.qualified_name] = node.id
                global_symbols.setdefault(node.qualified_name, []).append(node.id)

        if node.kind == METHOD and node.parent_id:
            class_methods.setdefault(node.parent_id, {})[node.name] = node.id

    file_imports_map: dict[str, list[str]] = {}
    named_imports_map: dict[str, dict[str, str]] = {}

    for imp in ctx.pending_imports:
        target_rel = _resolve_import(ctx, imp, file_paths)
        if target_rel:
            file_imports_map.setdefault(imp.importing_file_rel, []).append(target_rel)
            if imp.imported_names:
                for sym_name in imp.imported_names:
                    named_imports_map.setdefault(imp.importing_file_rel, {})[
                        sym_name
                    ] = target_rel

    for inh in ctx.pending_inheritances:
        _resolve_inheritance(
            ctx, inh, file_exports, file_imports_map, named_imports_map, global_symbols
        )

    for call in ctx.pending_calls:
        _resolve_call(
            ctx,
            call,
            class_methods,
            file_exports,
            file_imports_map,
            named_imports_map,
            global_symbols,
        )

def available_languages() -> dict[str, str | None]:
    """Return {language_id: None} for loadable languages, {language_id: error} otherwise."""
    result: dict[str, str | None] = {}
    for lang_id in _GRAMMAR_SOURCES:
        try:
            _load_spec(lang_id)
            result[lang_id] = None
        except Exception as exc:  # noqa: BLE001 - want to record any load failure
            result[lang_id] = str(exc)
    return result

def get_spec(lang_id: str) -> LanguageSpec | None:
    """Return the LanguageSpec for lang_id, or None if unavailable (missing grammar/query)."""
    try:
        return _load_spec(lang_id)
    except Exception:  # noqa: BLE001
        return None

def __getattr__(name: str):
    if name in ("main", "mcp"):
        from buddhi.mcp.server import main, mcp

        return {"main": main, "mcp": mcp}[name]
    raise AttributeError(f"module {__name__!r} has no attribute {name!r}")

def is_block_node(node_type: str) -> bool:
    nt = node_type.lower()
    return nt in ("block", "compound_statement", "statement_block")

def is_callable_parent(parent_type: str | None) -> bool:
    if not parent_type:
        return False
    pt = parent_type.lower()
    return (
        "function" in pt
        or "method" in pt
        or "constructor" in pt
        or "arrow" in pt
        or "lambda" in pt
        or "closure" in pt
    )

def count_tokens(text: str) -> int:
    """Counts the number of tokens using tiktoken if available, else standard char heuristic."""
    if not text:
        return 0

    try:
        import tiktoken  # type: ignore[import-not-found,import-untyped]

        encoder = tiktoken.get_encoding("cl100k_base")
        return len(encoder.encode(text))
    except Exception:  # noqa: BLE001
        # Standard heuristic: ~4 characters per token
        return max(1, len(text) // 4)

def filter_by_entropy(lines: list[str], threshold: float = 3.0) -> list[str]:
    """Filters out lines whose Shannon entropy is below the threshold.

    Blank lines or repetitive boilerplate (e.g. `// ##########`) will be pruned.
    """
    filtered_lines: list[str] = []
    for line in lines:
        stripped = line.strip()
        if calculate_entropy(stripped) >= threshold:
            filtered_lines.append(line)

    return filtered_lines

def _native_grep_search(query: str, root_path: Path | None = None) -> str:
    """Fuzzy/regex search files recursively in the workspace as a fallback."""
    matches: list[str] = []
    p = root_path if root_path else Path(".")
    try:
        pattern = re.compile(query, re.IGNORECASE)
    except re.error:
        pattern = re.compile(re.escape(query), re.IGNORECASE)

    try:
        for path in p.rglob("*"):
            if path.is_file():
                parts = path.parts
                if not any(
                    ignored in parts
                    for ignored in (
                        ".git",
                        "node_modules",
                        ".buddhi",
                        ".venv",
                        "venv",
                        ".agents",
                        "__pycache__",
                    )
                ):
                    try:
                        with path.open("r", encoding="utf-8", errors="replace") as f:
                            for idx, line in enumerate(f, 1):
                                if pattern.search(line):
                                    display_path = (
                                        path.relative_to(p).as_posix()
                                        if root_path and path.is_relative_to(p)
                                        else path.as_posix()
                                    )
                                    matches.append(
                                        f"{display_path}:{idx}: {line.strip()}"
                                    )
                                    if len(matches) >= 50:
                                        break
                    except (OSError, UnicodeDecodeError):
                        pass
            if len(matches) >= 50:
                break
    except (OSError, UnicodeDecodeError):
        pass

    if matches:
        return (
            "### [fallback: native grep] Native Grep Fallback Matches:\n"
            + "\n".join(matches)
        )
    return ""

def extract_signature(content: str, signature: str, node_type: str) -> str:
    """Extract or return signature and docstring from definition."""
    if signature and signature.strip():
        return signature.strip()

    if not content:
        return content

    lines = content.splitlines()
    nt = node_type.lower()
    if "function" in nt or "method" in nt or "class" in nt:
        sig_lines: list[str] = []
        found_colon = False
        for line in lines:
            sig_lines.append(line)
            if not found_colon and (
                line.rstrip().endswith(":") or line.rstrip().endswith("{")
            ):
                found_colon = True
                continue
            if found_colon:
                stripped = line.strip()
                if stripped.startswith(('"""', "'''", "/*")):
                    sig_lines.append(line)
                    if (
                        stripped.count('"""') >= 2
                        or stripped.count("'''") >= 2
                        or "*/" in stripped
                    ):
                        break
                    for remaining in lines[len(sig_lines) :]:
                        sig_lines.append(remaining)
                        if (
                            '"""' in remaining
                            or "'''" in remaining
                            or "*/" in remaining
                        ):
                            break
                break

        if sig_lines:
            return "\n".join(sig_lines)

    return lines[0] if lines else content

def filter_low_entropy_lines(
    content: str, threshold: float = _ENTROPY_THRESHOLD
) -> str:
    """Remove lines with Shannon entropy below the threshold."""
    if not content:
        return content

    lines = content.splitlines()
    filtered: list[str] = []

    for line in lines:
        stripped = line.strip()
        if not stripped or len(stripped) < 10:
            filtered.append(line)
            continue

        entropy = calculate_entropy(stripped)
        if entropy >= threshold:
            filtered.append(line)

    return "\n".join(filtered)

def render_content(result: SearchResult) -> str:
    """Render node content according to its current mode."""
    if result.mode == "map":
        return extract_map_entry(result)

    if result.mode == "signatures":
        content = extract_signature(result.content, result.signature, result.node_type)
    else:
        content = result.content or result.signature

    return filter_low_entropy_lines(content)

def serialize_context(nodes: list[SearchResult]) -> str:
    """Serialize search results into delimited text with boundary markers."""
    if not nodes:
        return ""

    blocks: list[str] = []
    for result in nodes:
        header = f"--- START SYMBOL: {result.file_path}::{result.name} (L{result.start_line}-L{result.end_line}) ---"
        content = render_content(result)
        footer = "--- END SYMBOL ---"
        blocks.append(f"{header}\n{content}\n{footer}")

    return "\n\n".join(blocks)

def split_frontmatter(content: str) -> tuple[dict[str, Any], str]:
    """Splits YAML frontmatter from markdown body.

    Returns (metadata_dict, body_str). If no frontmatter delimiter is present,
    returns ({}, content).
    """
    match = _FRONTMATTER_SPLIT_RE.match(content)
    if not match:
        return {}, content.strip()

    raw_yaml, body = match.group(1), match.group(2)
    try:
        data = yaml.safe_load(raw_yaml) or {}
    except (yaml.YAMLError, OSError, ValueError):
        data = {}

    if not isinstance(data, dict):
        data = {}

    # Reject forbidden Attested Computation fields
    for forbidden in _FORBIDDEN_OKF_FIELDS:
        data.pop(forbidden, None)

    return data, body.strip()

def is_boilerplate(line: str) -> bool:
    """Check if line is template boilerplate rather than user entry."""
    cleaned = line.lower().strip()
    return any(bp in cleaned for bp in BOILERPLATE_SUBSTRINGS)

def parse_legacy_entries(text: str) -> list[str]:
    """Parse distinct bullet points, numbered items, or paragraph entries."""
    lines = text.splitlines()
    entries: list[str] = []
    current_entry: list[str] = []

    for line in lines:
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        if is_boilerplate(stripped):
            continue

        if stripped.startswith(("- ", "* ", "+ ")) or re.match(r"^\d+\.\s+", stripped):
            if current_entry:
                entries.append(" ".join(current_entry))
                current_entry = []
            clean_item = re.sub(r"^[-*+\d.]+\s*", "", stripped)
            current_entry.append(clean_item)
        else:
            current_entry.append(stripped)

    if current_entry:
        entries.append(" ".join(current_entry))

    return [e.strip() for e in entries if e.strip()]

def matches_active_files(patterns: list[str], active_files: list[str]) -> bool:
    """Returns True if patterns is empty (global) or matches any active file."""
    if not patterns:
        return True

    if not active_files:
        return False

    normalized_files = [f.replace("\\", "/").lstrip("/") for f in active_files]
    spec = pathspec.PathSpec.from_lines("gitignore", patterns)

    for f in normalized_files:
        if spec.match_file(f):
            return True

    return False

def _find_spec_dir(workspace_root: Path, branch: str | None = None) -> Path | None:
    specs_root = workspace_root / ".buddhi" / "specs"
    if not specs_root.is_dir():
        return None

    if branch:
        target = specs_root / branch
        if target.is_dir():
            return target
        done_target = specs_root / "done" / branch
        if done_target.is_dir():
            return done_target
        return None

    # Search for any active spec directory with spec.md
    candidates = [
        d
        for d in specs_root.iterdir()
        if d.is_dir() and d.name != "done" and (d / "spec.md").is_file()
    ]
    if candidates:
        return candidates[0]

    return None

def assert_no_secrets_in_tracked_memory(content: str, scope: str) -> None:
    """Blocks secrets/credentials from being persisted into git-tracked scopes."""
    if scope in ("local", "agent-local"):
        return

    for pattern in SECRET_PATTERNS:
        if pattern.search(content):
            raise PermissionError(
                "Potential secret or credential detected in memory content. "
                "Credentials must never be saved to git-tracked 'project' memory. "
                "Use scope 'local' or store credentials in environment variables."
            )

def parse_source_resource(
    resource: str, workspace_root: Path
) -> tuple[Path, int | None, int | None]:
    """Parses and validates a code source anchor ('path/file.py#L10-L20')."""
    path_part, _, line_part = resource.partition("#")
    cleaned = path_part.strip().replace("\\", "/")
    if cleaned.startswith(("/", "\\")) or ".." in Path(cleaned).parts:
        raise PermissionError(
            f"Source resource '{resource}' uses absolute or parent traversal path"
        )

    target = (workspace_root / cleaned).resolve()
    ws_resolved = workspace_root.resolve()
    if not target.is_relative_to(ws_resolved):
        raise PermissionError(f"Source resource '{resource}' escapes workspace root")

    start_line, end_line = None, None
    if line_part:
        m = re.match(r"^L(\d+)(?:-L(\d+))?$", line_part.strip())
        if not m:
            raise ValueError(f"Invalid line range in source anchor: #{line_part}")
        start_line = int(m.group(1))
        end_line = int(m.group(2)) if m.group(2) else start_line
        if start_line <= 0 or end_line < start_line:
            raise ValueError(f"Invalid line range bounds: L{start_line}-L{end_line}")

    return target, start_line, end_line

def compute_content_hash(workspace_root: Path, resource: str) -> str:
    """Computes SHA-256 of full file or line slice #Lstart-Lend with normalized LF line endings."""
    file_path, start_line, end_line = parse_source_resource(resource, workspace_root)
    if not file_path.is_file():
        raise FileNotFoundError(f"Source file not found: {file_path}")

    raw_text = file_path.read_text(encoding="utf-8")
    # Normalize CRLF -> LF for cross-platform hash parity
    normalized = raw_text.replace("\r\n", "\n")

    if start_line is not None and end_line is not None:
        lines = normalized.splitlines(keepends=True)
        # 1-indexed line numbers
        selected = lines[start_line - 1 : end_line]
        slice_text = "".join(selected)
    else:
        slice_text = normalized

    return hashlib.sha256(slice_text.encode("utf-8")).hexdigest()

def verify_source_staleness(
    workspace_root: Path, source: MemorySource
) -> StalenessResult:
    """Checks whether the on-disk code snippet still matches source.content_hash."""
    try:
        current_hash = compute_content_hash(workspace_root, source.resource)
    except FileNotFoundError:
        return StalenessResult(
            is_stale=True,
            reason="file_not_found",
            expected_hash=source.content_hash,
            current_hash="",
        )
    except ValueError as exc:
        return StalenessResult(
            is_stale=True,
            reason=f"invalid_resource: {exc}",
            expected_hash=source.content_hash,
            current_hash="",
        )

    if current_hash != source.content_hash:
        return StalenessResult(
            is_stale=True,
            reason="hash_mismatch",
            expected_hash=source.content_hash,
            current_hash=current_hash,
        )

    return StalenessResult(
        is_stale=False,
        reason=None,
        expected_hash=source.content_hash,
        current_hash=current_hash,
    )

def resolve_and_sandbox_import(
    raw_ref: str,
    base_dir: Path,
    workspace_root: Path,
    user_memory_root: Path,
) -> Path:
    """Resolves an `@path` import string while strictly enforcing workspace / user-memory sandboxing."""
    cleaned = raw_ref.lstrip("@").strip()
    if "\0" in cleaned or "\r" in cleaned or "\n" in cleaned:
        raise ValueError(f"Invalid characters in import path: '{raw_ref}'")

    if cleaned.startswith(("\\\\", "//")):
        raise PermissionError(f"UNC network paths forbidden: '{raw_ref}'")

    # Base path resolution
    if cleaned.startswith("~"):
        target = Path(cleaned).expanduser()
    elif cleaned.startswith("/") or (
        len(cleaned) > 2 and cleaned[1] == ":" and cleaned[2] in "\\/"
    ):
        target = Path(cleaned)
    else:
        # Relative to current file directory if exists, otherwise relative to workspace root
        from_base = (base_dir / cleaned).resolve()
        if from_base.exists():
            target = from_base
        else:
            target = (workspace_root / cleaned).resolve()

    try:
        resolved = target.resolve(strict=True)
    except (FileNotFoundError, RuntimeError, OSError) as exc:
        raise FileNotFoundError(f"Cannot resolve import '{raw_ref}': {exc}") from exc

    ws_resolved = workspace_root.resolve()
    user_resolved = user_memory_root.resolve()

    in_workspace = resolved.is_relative_to(ws_resolved)
    in_user = resolved.is_relative_to(user_resolved)

    if not (in_workspace or in_user):
        raise PermissionError(
            f"Sandbox escape blocked: '{raw_ref}' resolves outside permitted roots"
        )

    if not resolved.is_file():
        raise ValueError(f"Import target is not a regular file: '{raw_ref}'")

    return resolved

def build_memory_file_path(base_memory_dir: Path, kind: str, slug: str) -> Path:
    """Builds and validates an atomic concept file path inside base_memory_dir."""
    if ".." in slug or "/" in slug or "\\" in slug:
        raise PermissionError(
            f"Slug traversal blocked: '{slug}' contains path separators or traversal characters"
        )
    topic_sub = TOPIC_DIRS.get(kind, "misc")
    clean_slug = sanitize_slug(slug)
    target = (base_memory_dir / topic_sub / f"{clean_slug}.md").resolve()
    base_resolved = base_memory_dir.resolve()
    if not target.is_relative_to(base_resolved):
        raise PermissionError(
            f"Slug traversal blocked: '{slug}' resolves outside memory base directory"
        )
    return target

def atomic_write_bytes(path: Path, data: bytes) -> None:
    tmp_path = path.with_name(f"{path.name}.tmp-{os.getpid()}")
    try:
        tmp_path.write_bytes(data)
        os.replace(tmp_path, path)
    except BaseException:
        tmp_path.unlink(missing_ok=True)
        raise

def _community_color(community_id: int) -> dict[str, str]:
    hue = (community_id * 0.618033988749895) % 1.0
    r, g, b = colorsys.hsv_to_rgb(hue, 0.6, 0.9)
    background = f"#{int(r * 255):02x}{int(g * 255):02x}{int(b * 255):02x}"
    return {"background": background, "border": "#f8fafc"}

def _legend_html() -> str:
    return "".join(
        _LEGEND_ITEM.format(
            color=_KIND_COLORS[kind]["background"], label=label, kind=kind
        )
        for kind, label in _KIND_LABELS
    )

def _node_color(kind: str, community_id: int | None) -> dict[str, str]:
    if kind in _CLUSTERABLE_KINDS and community_id is not None:
        return _community_color(community_id)
    return _KIND_COLORS.get(kind, {"background": "#3b82f6", "border": "#60a5fa"})

def _build_vis_data(graph: CodeGraph) -> dict:
    nodes = []
    for node in graph.nodes.values():
        color = _node_color(node.kind, node.community_id)
        nodes.append(
            {
                "id": node.id,
                "label": node.name,
                "kind": node.kind,
                "qualified_name": node.qualified_name,
                "file_path": node.file_path,
                "start_line": node.start_line,
                "end_line": node.end_line,
                "snippet": node.snippet,
                "community_id": node.community_id,
                "color": {
                    "background": color["background"],
                    "border": color["border"],
                    "highlight": {
                        "background": color["background"],
                        "border": "#f8fafc",
                    },
                    "hover": {"background": color["background"], "border": "#f8fafc"},
                },
            }
        )

    edges = []
    for edge in graph.edges:
        if edge.kind == CONTAINS:
            continue
        edges.append(
            {
                "from": edge.source,
                "to": edge.target,
                "kind": edge.kind,
                "color": {
                    "color": _EDGE_COLORS.get(edge.kind, "#64748b"),
                    "opacity": 0.5,
                },
            }
        )

    return {"nodes": nodes, "edges": edges}

def to_cytoscape_elements(graph: CodeGraph) -> dict:
    nodes = []
    for node in graph.nodes.values():
        data = {
            "id": node.id,
            "label": node.name,
            "kind": node.kind,
            "qualified_name": node.qualified_name,
            "file_path": node.file_path,
            "language": node.language,
            "start_line": node.start_line,
            "end_line": node.end_line,
            "external": node.external,
            "snippet": node.snippet,
            "community_id": node.community_id,
        }
        if node.parent_id:
            data["parent"] = node.parent_id
        nodes.append({"data": data})

    edges = []
    for i, edge in enumerate(graph.edges):
        edges.append(
            {
                "data": {
                    "id": f"e{i}",
                    "source": edge.source,
                    "target": edge.target,
                    "kind": edge.kind,
                    "resolved": edge.resolved,
                    "confidence": edge.confidence,
                    "confidence_score": edge.confidence_score,
                    "context": edge.context,
                }
            }
        )

    communities = [
        {
            "id": c.id,
            "label": c.label,
            "node_count": c.node_count,
            "cohesion": c.cohesion,
            "hub_node_id": c.hub_node_id,
            "top_files": c.top_files,
        }
        for c in graph.communities.values()
    ]

    return {
        "nodes": nodes,
        "edges": edges,
        "communities": communities,
        "built_at_commit": graph.built_at_commit,
    }

def get_db_capabilities(conn: sqlite3.Connection) -> dict[str, bool]:
    """Inspect SQLite database capabilities to ensure backward compatibility."""
    tables = {
        r[0] for r in conn.execute("SELECT name FROM sqlite_master WHERE type='table'")
    }
    edge_cols = (
        {r[1] for r in conn.execute("PRAGMA table_info(edges)")}
        if "edges" in tables
        else set()
    )
    return {
        "has_communities": "communities" in tables,
        "has_extract_cache": "extract_cache" in tables,
        "has_edge_confidence": "confidence" in edge_cols,
        "has_edge_context": "context" in edge_cols,
    }

def get_community_detail(conn: sqlite3.Connection, community_id: int) -> dict[str, Any]:
    """Return member nodes and community info."""
    caps = get_db_capabilities(conn)
    comm_info: dict[str, Any] = {"id": community_id}
    if caps["has_communities"]:
        row = conn.execute(
            "SELECT label, node_count, cohesion, hub_node_id FROM communities WHERE id = ?",
            (community_id,),
        ).fetchone()
        if row:
            comm_info.update(
                {
                    "label": row[0],
                    "node_count": row[1],
                    "cohesion": row[2],
                    "hub_node_id": row[3],
                }
            )

    members = [
        {"id": r[0], "name": r[1], "kind": r[2], "file_path": r[3]}
        for r in conn.execute(
            "SELECT id, name, kind, file_path FROM nodes WHERE community_id = ?",
            (community_id,),
        ).fetchall()
    ]
    comm_info["members"] = members
    return comm_info

def suggest_questions(conn: sqlite3.Connection, top_n: int = 7) -> list[dict[str, Any]]:
    """Synthesize architectural review questions across 5 diagnostic categories."""
    caps = get_db_capabilities(conn)
    questions: list[dict[str, Any]] = []

    # 1. Low cohesion communities
    if caps["has_communities"]:
        cur = conn.execute(
            "SELECT id, label, cohesion, node_count FROM communities WHERE cohesion < 0.15 AND node_count >= 5 ORDER BY cohesion ASC LIMIT 2"
        )
        for row in cur.fetchall():
            questions.append(
                {
                    "category": "low_cohesion",
                    "target": f"Community {row[0]} ({row[1]})",
                    "question": f"Community '{row[1]}' has low internal cohesion ({row[2]}). Should its {row[3]} components be decoupled into distinct modules?",
                }
            )

    # 2. Ambiguous edges
    if caps["has_edge_confidence"]:
        cur = conn.execute(
            "SELECT source_id, target_id, kind FROM edges WHERE confidence = 'AMBIGUOUS' LIMIT 2"
        )
        for row in cur.fetchall():
            questions.append(
                {
                    "category": "ambiguous_edge",
                    "target": f"{row[0]} -> {row[1]}",
                    "question": f"Edge {row[0]} -> {row[1]} ({row[2]}) is ambiguous. Is this dependency intended or an accidental name collision?",
                }
            )

    # 3. God nodes
    gods = get_god_nodes(conn, top_n=2)
    for g in gods:
        questions.append(
            {
                "category": "bridge_node",
                "target": g["id"],
                "question": f"Symbol '{g['name']}' in {g['file_path']} has high incident degree ({g['degree']}). Does it represent a god object that warrants refactoring?",
            }
        )

    return questions[:top_n]

def load_extract_cache(db_path: Path) -> dict[str, tuple[str, str, str, str]]:
    """Load existing (file_path -> (sha256, language, payload_json, updated_at)) from tree-graph.db."""
    if not db_path.is_file():
        return {}

    try:
        conn = sqlite3.connect(f"file:{db_path.resolve().as_posix()}?mode=ro", uri=True)
        try:
            caps = get_db_capabilities(conn)
            if not caps["has_extract_cache"]:
                return {}
            cursor = conn.cursor()
            cursor.execute(
                "SELECT file_path, sha256, language, payload_json, updated_at FROM extract_cache"
            )
            return {
                row[0]: (row[1], row[2], row[3], row[4]) for row in cursor.fetchall()
            }
        finally:
            conn.close()
    except (sqlite3.OperationalError, sqlite3.DatabaseError, OSError):
        return {}

def read_settings(file: Path | None = None) -> dict[str, Any]:
    target = file if file is not None else settings_path
    if not target.exists():
        return {}
    try:
        data = json.loads(target.read_text(encoding="utf-8"))
    except Exception as exc:
        raise ValueError(f"Cannot read {target}: {exc}") from exc

    if not isinstance(data, dict):
        raise ValueError(f"Expected a JSON object in {target}")  # noqa: TRY004
    return data

def configure_mode(mode: str | None = None, file: Path | None = None) -> str:
    target = file if file is not None else settings_path
    if mode is not None and mode not in MODES:
        raise ValueError(f"Invalid mode in {target}. Set --mode during, after, or ask.")

    try:
        settings = read_settings(target)
    except ValueError as exc:
        raise ValueError(f"{exc} Fix or delete it to start over.") from exc

    if mode is not None:
        settings["mode"] = mode
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(json.dumps(settings, indent=2) + "\n", encoding="utf-8")

    resolved_mode = settings.get("mode") or "ask"
    if resolved_mode not in MODES:
        raise ValueError(f"Invalid mode in {target}. Set --mode during, after, or ask.")

    default_indicator = " (default)" if "mode" not in settings else ""
    return f"antislop global mode: {resolved_mode}{default_indicator}\n{target}"

def antislop_mode(
    mode: str | None = typer.Argument(
