    except ValueError as exc:
        err_console.print(f"error: {exc}")
        raise typer.Exit(code=1)

    console.print(output)

def atomic_write_bytes(target_path: Path, data: bytes) -> None:
    """Atomically write binary data to target_path, preserving existing mode if present."""
    target_path = target_path.resolve()
    target_path.parent.mkdir(parents=True, exist_ok=True)

    mode = 0o644
    if target_path.exists():
        try:
            mode = target_path.stat().st_mode & 0o777
        except OSError:
            pass

    fd, temp_file = tempfile.mkstemp(
        prefix=f".{target_path.name}.",
        suffix=".tmp",
        dir=str(target_path.parent),
    )
    try:
        with os.fdopen(fd, "wb") as f:
            f.write(data)
            f.flush()
            os.fsync(f.fileno())

        try:
            os.chmod(temp_file, mode)
        except OSError:
            pass

        os.replace(temp_file, str(target_path))
    except Exception:
        try:
            if os.path.exists(temp_file):
                os.remove(temp_file)
        except OSError:
            pass
        raise

def atomic_write_text(target_path: Path, content: str, encoding: str = "utf-8") -> None:
    """Atomically write text content to target_path."""
    atomic_write_bytes(target_path, content.encode(encoding))

def check_markdown_links(root: Path) -> list[dict[str, str]]:
    """Scan markdown files for broken relative links, skipping .archive directories."""
    broken: list[dict[str, str]] = []

    for dirpath, dirnames, filenames in os.walk(root):
        # Skip .archive, .git, .venv, node_modules
        dirnames[:] = [
            d
            for d in dirnames
            if d not in (".archive", ".git", ".venv", "node_modules", "temp")
        ]

        for fname in filenames:
            if not fname.endswith(".md"):
                continue

            md_path = Path(dirpath) / fname
            try:
                content = md_path.read_text(encoding="utf-8")
            except OSError:
                continue

            lines = content.splitlines()
            for idx, line in enumerate(lines, start=1):
                for match in _LINK_RE.finditer(line):
                    raw_target = match.group(1).split("#")[0].strip()
                    if not raw_target:
                        continue

                    target_path = (md_path.parent / raw_target).resolve()
                    if not target_path.exists():
                        broken.append(
                            {
                                "source_file": str(md_path),
                                "line": str(idx),
                                "target": raw_target,
                            }
                        )

    return broken

def autoharness_check_links_cmd(
