        )
        raise typer.Exit(code=0)
    else:
        err_console.print(
            f"[bold red]fail:[/bold red] found {len(broken)} broken relative markdown link(s):"
        )
        for b in broken:
            err_console.print(f"  {b['source_file']}:{b['line']} -> {b['target']}")
        raise typer.Exit(code=1)

