    q_file = get_queue_file(layer, run_id, project_root)
    lock_file = q_file.parent / f"{run_id}.lock"
    with file_lock(lock_file):
        if q_file.is_file():
            q_file.unlink()

def passes_luhn(card_str: str) -> bool:
    """Check Luhn checksum for 13 to 16 digit card numbers."""
    digits = [int(c) for c in card_str if c.isdigit()]
    if len(digits) < 13 or len(digits) > 16:
        return False
    checksum = 0
    reverse_digits = digits[::-1]
    for i, d in enumerate(reverse_digits):
        if i % 2 == 1:
            doubled = d * 2
            checksum += doubled - 9 if doubled > 9 else doubled
        else:
            checksum += d
    return checksum % 10 == 0

def redact_text(text: str) -> str:
    """Single-pass non-overlapping redaction replacing secret and PII hits with tagged tokens."""
    matches: list[tuple[int, int, str]] = []

    # Collect secret matches
    for name, pattern in SECRET_PATTERNS:
        for m in pattern.finditer(text):
            matches.append((m.start(), m.end(), f"[REDACTED:secret:{name}]"))

    # Collect PII matches
    for name, pattern in PII_PATTERNS:
        for m in pattern.finditer(text):
            if name == "credit_card":
                raw = text[m.start() : m.end()]
                if not passes_luhn(raw):
                    continue
            matches.append((m.start(), m.end(), f"[REDACTED:pii:{name}]"))

    if not matches:
        return text

    # Sort matches by start position, earliest start first, longest match first
    matches.sort(key=lambda x: (x[0], -(x[1] - x[0])))

    # Filter out overlapping matches
    filtered: list[tuple[int, int, str]] = []
    last_end = 0
    for start, end, repl in matches:
        if start >= last_end:
            filtered.append((start, end, repl))
            last_end = end

    # Build redacted output string
    result: list[str] = []
    curr = 0
    for start, end, repl in filtered:
        result.append(text[curr:start])
        result.append(repl)
        curr = end
    result.append(text[curr:])
    return "".join(result)

def build_prior_digest(transcript_path: Path, end_offset: int) -> str:
    """Read prior records before end_offset and build a concise summary of user/agent steps."""
    if not transcript_path.is_file() or end_offset <= 0:
        return ""

    exchanges: list[str] = []
    with open(transcript_path, "r", encoding="utf-8", errors="replace") as f:
        curr_offset = 0
        for line in f:
            if curr_offset >= end_offset:
                break
            curr_offset = f.tell()
            line_str = line.strip()
            if not line_str:
                continue

            try:
                rec = json.loads(line_str)
                role = rec.get("source", rec.get("role", "system"))
                content = str(rec.get("content", ""))[:150]
                if content:
                    exchanges.append(f"[{role}]: {content}")
            except json.JSONDecodeError:
                pass

    recent = exchanges[-DIGEST_EXCHANGES:]
    raw_digest = "\n".join(recent)[:MAX_DIGEST_BYTES]
    return redact_text(raw_digest)

def secret_hits(text: str) -> list[str]:
    """Scan text and return names of any secret rules hit (used for admission gating)."""
    hits: list[str] = []
    for name, pattern in SECRET_PATTERNS:
        if pattern.search(text):
            hits.append(name)
    return hits

def read_sidecar(skill_dir: Path) -> SidecarData | None:
    """Read .sidecar.json from skill_dir. Returns None if absent or malformed."""
    sidecar_path = skill_dir / SIDECAR_FILENAME
    if not sidecar_path.is_file():
        return None
    try:
        raw = sidecar_path.read_text(encoding="utf-8")
        data = json.loads(raw)
        return SidecarData(
            created_by=data.get("created_by", "human"),
            use=int(data.get("use", data.get("calls", 0))),
            view=int(data.get("view", 0)),
            patch=int(data.get("patch", 0)),
            reused_gen=int(data.get("reused_gen", 0)),
            anchor=int(data.get("anchor", 0)),
            verification=data.get("verification", {}),
        )
    except (OSError, json.JSONDecodeError, ValueError):
        return None

def collect_metrics(layer: str = "project", project_root: Path | None = None) -> dict:
    """Collect telemetry metrics across active agent-authored skills and runs."""
    skills_dir = resolve_skills_dir(layer, project_root)
    autoharness_dir = resolve_autoharness_dir(layer, project_root)

    total_live = 0
    total_uses = 0
    total_views = 0
    total_patches = 0

    if skills_dir.is_dir():
        for item in skills_dir.iterdir():
            if item.is_dir() and is_agent_created(item):
                sidecar = read_sidecar(item)
                if sidecar:
                    total_live += 1
                    total_uses += sidecar.use
                    total_views += sidecar.view
                    total_patches += sidecar.patch

    archive_dir = skills_dir / ".archive"
    total_archived = len(list(archive_dir.iterdir())) if archive_dir.is_dir() else 0

    last_run_file = autoharness_dir / "last_run.json"
    last_run_data = {}
    if last_run_file.is_file():
        try:
            last_run_data = json.loads(last_run_file.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            pass

    return {
        "layer": layer,
        "live_skills": total_live,
        "total_uses": total_uses,
        "total_views": total_views,
        "total_patches": total_patches,
        "archived_skills": total_archived,
        "last_run": last_run_data,
    }

def bump_sidecar_counter(skill_dir: Path, counter_name: str, delta: int = 1) -> None:
    """Atomically increment a counter in .sidecar.json under file lock."""
    lock_path = skill_dir / f"{SIDECAR_FILENAME}.lock"
    with file_lock(lock_path):
        sidecar = read_sidecar(skill_dir)
        if sidecar is None:
            return
        if counter_name == "use":
            sidecar.use += delta
        elif counter_name == "view":
            sidecar.view += delta
        elif counter_name == "patch":
            sidecar.patch += delta
        elif counter_name == "reused_gen":
            sidecar.reused_gen += delta
        write_sidecar(skill_dir, sidecar)

def apply_delta(current_body: str, old_string: str, new_string: str) -> str:
    """Apply exact string replacement to current_body, ensuring unique match."""
    count = current_body.count(old_string)
    if count == 0:
        raise ValueError(
            f"Target old_string '{old_string[:50]}...' not found in SKILL.md."
        )
    if count > 1:
        raise ValueError(
            f"Target old_string matches {count} occurrences in SKILL.md; must be unique."
        )
    return current_body.replace(old_string, new_string, 1)

def read_body(skills_dir: Path, name: str) -> str | None:
