def remove_subfile(skill_dir: Path, rel_path: str) -> None:
    target = skill_dir / rel_path
    if target.is_file():
        target.unlink()

def sweep_orphans(skills_dir: Path) -> int:
    """Clean up orphan .tmp files left over from aborted writes."""
    swept = 0
    if not skills_dir.is_dir():
        return 0
    for root, _, files in os.walk(skills_dir):
        for f in files:
            if f.endswith(".tmp") or (f.startswith(".") and ".tmp" in f):
                try:
                    os.remove(os.path.join(root, f))
                    swept += 1
                except OSError:
                    pass
    return swept

def scan(text: str) -> list[dict[str, str]]:
    """Scan text across all 6 threat families and return list of violation records."""
    violations: list[dict[str, str]] = []
    lines = text.splitlines()

    for family, patterns in THREAT_FAMILIES.items():
        for pat in patterns:
            for idx, line in enumerate(lines):
                m = pat.search(line)
                if m:
                    violations.append(
                        {
                            "family": family,
                            "line": str(idx + 1),
                            "snippet": line.strip()[:100],
                        }
                    )
    return violations

def format_tokens(num_bytes: int) -> str:
    toks = round(num_bytes / 4)
    return f"~{toks:,} tokens"

def get_unauthored(paths: list[str]) -> set[str]:
    """Return paths marked linguist-generated or linguist-vendored in git index."""
    if not paths:
        return set()
    input_data = "\0".join(paths).encode("utf-8")
    try:
        proc = subprocess.run(
            [
                "git",
                "check-attr",
                "--cached",
                "-z",
                "--stdin",
                "linguist-generated",
                "linguist-vendored",
            ],
            input=input_data,
            capture_output=True,
            check=True,
        )
        parts = proc.stdout.decode("utf-8", errors="replace").split("\0")
        marked = set()
        for i in range(0, len(parts) - 2, 3):
            attr_val = parts[i + 2]
            if attr_val in ("true", "set"):
                marked.add(parts[i])
        return marked
    except (subprocess.CalledProcessError, OSError):
        return set()

def is_ignored(spec: str) -> bool:
    """Check if the first PRAGMA_LINES contain @ratchet-files-ignore."""
    try:
        proc = subprocess.run(
            ["git", "cat-file", "blob", spec],
            capture_output=True,
            check=True,
        )
        lines = proc.stdout.decode("utf-8", errors="replace").splitlines()
        first_lines = lines[:PRAGMA_LINES]
        return any(PRAGMA in line for line in first_lines)
    except (subprocess.CalledProcessError, OSError):
        return False

def is_source_file(path_str: str) -> bool:
    ext = os.path.splitext(path_str)[1].lower()
    if not ext:
        return False
    return ext in CODE_EXTENSIONS and ext not in PROSE_EXTENSIONS

def run_git(args: list[str], input_bytes: bytes | None = None) -> str:
    """Execute git with pipe stdio and utf-8 decoding."""
    result = subprocess.run(
        ["git", *args],
        input=input_bytes,
        capture_output=True,
        check=True,
    )
    return result.stdout.decode("utf-8", errors="replace")

def blob_bytes(spec: str) -> int | None:
    """Return byte size of a git blob spec (e.g. ':path' or 'HEAD:path')."""
    try:
        out = run_git(["cat-file", "-s", spec]).strip()
        return int(out)
    except (subprocess.CalledProcessError, OSError, ValueError):
        return None

def get_git_root() -> Path:
    """Return git repo toplevel directory."""
    out = run_git(["rev-parse", "--show-toplevel"]).strip()
    return Path(out).resolve()

def composite(
    fg: tuple[int, int, int, float], bg: tuple[int, int, int]
) -> tuple[int, int, int]:
    a = fg[3]
    return (
        round(fg[0] * a + bg[0] * (1 - a)),
        round(fg[1] * a + bg[1] * (1 - a)),
        round(fg[2] * a + bg[2] * (1 - a)),
    )

def linearize(channel: int) -> float:
    c = channel / 255.0
    if c <= 0.04045:
        return c / 12.92
    return ((c + 0.055) / 1.055) ** 2.4

def luminance(rgb: tuple[int, int, int]) -> float:
    r, g, b = (linearize(ch) for ch in rgb)
    return 0.2126 * r + 0.7152 * g + 0.0722 * b

def contrast_ratio(
    color_a: tuple[int, int, int], color_b: tuple[int, int, int]
) -> float:
    lum_a, lum_b = luminance(color_a), luminance(color_b)
    lighter, darker = max(lum_a, lum_b), min(lum_a, lum_b)
    return (lighter + 0.05) / (darker + 0.05)

def parse_color_extended(
    token: str,
) -> tuple[int, int, int, float] | None:
    t = token.strip().lower()
    if t in NAMED_COLORS:
        r, g, b = NAMED_COLORS[t]
        return (r, g, b, 1.0)
    if t.startswith("#"):
        h = t[1:]
        if len(h) in (3, 4):
            h = "".join(c * 2 for c in h)
        if len(h) == 6:
            h += "ff"
        if len(h) != 8:
            return None
        try:
            r, g, b, a = (
                int(h[0:2], 16),
                int(h[2:4], 16),
                int(h[4:6], 16),
                int(h[6:8], 16) / 255.0,
            )
            return (r, g, b, a)
        except ValueError:
            return None
    m = re.match(r"(rgba?|hsla?)\(([^)]+)\)", t)
    if not m:
        return None
    fn, body = m.group(1), m.group(2)
    parts = [p.strip() for p in re.split(r"[,/]", body) if p.strip()]
    if len(parts) < 3:
        return None
    try:
        if fn.startswith("rgb"):
            vals = []
            for p in parts[:3]:
                vals.append(float(p[:-1]) * 2.55 if p.endswith("%") else float(p))
            a = (
                float(parts[3][:-1]) / 100
                if len(parts) > 3 and parts[3].endswith("%")
                else float(parts[3])
                if len(parts) > 3
                else 1.0
            )
            return (
                round(_clamp(vals[0])),
                round(_clamp(vals[1])),
                round(_clamp(vals[2])),
                a,
            )
        # hsl
        h_str = re.sub(r"deg$", "", parts[0])
        h_val = float(h_str) % 360
        s = float(parts[1].rstrip("%")) / 100
        l = float(parts[2].rstrip("%")) / 100
        a = (
            float(parts[3][:-1]) / 100
            if len(parts) > 3 and parts[3].endswith("%")
            else float(parts[3])
            if len(parts) > 3
            else 1.0
        )
        c = (1 - abs(2 * l - 1)) * s
        x = c * (1 - abs((h_val / 60) % 2 - 1))
        mm = l - c / 2
        if h_val < 60:
            r1, g1, b1 = (c, x, 0.0)
        elif h_val < 120:
            r1, g1, b1 = (x, c, 0.0)
        elif h_val < 180:
            r1, g1, b1 = (0.0, c, x)
        elif h_val < 240:
            r1, g1, b1 = (0.0, x, c)
        elif h_val < 300:
            r1, g1, b1 = (x, 0.0, c)
        else:
            r1, g1, b1 = (c, 0.0, x)
        return (
            round((r1 + mm) * 255),
            round((g1 + mm) * 255),
            round((b1 + mm) * 255),
            a,
        )
    except (ValueError, ZeroDivisionError):
        return None

def parse_hex(value: str) -> tuple[int, int, int]:
    clean = value.strip().lstrip("#")
    if len(clean) == 3:
        clean = "".join(ch * 2 for ch in clean)
    if not re.fullmatch(r"[0-9A-Fa-f]{6}", clean):
        raise ValueError(f"expected a hex color like #FFFFFF, got {value!r}")
    return (int(clean[0:2], 16), int(clean[2:4], 16), int(clean[4:6], 16))

def parse_color(value: str) -> tuple[int, int, int]:
    val = value.strip().lower()
    if val in NAMED_COLORS:
        return NAMED_COLORS[val]
    parsed = parse_color_extended(val)
    if parsed is not None:
        return (parsed[0], parsed[1], parsed[2])
    return parse_hex(value)

def parse_pairing(
    pairing: str,
) -> tuple[tuple[int, int, int], tuple[int, int, int]]:
    colors = []
    for token in re.split(r"\s+on\s+", pairing):
        token = token.strip()
        match = re.search(r"#[0-9A-Fa-f]{3,6}", token)
        if match:
            colors.append(parse_hex(match.group(0)))
        elif token.lower() in NAMED_COLORS:
            colors.append(NAMED_COLORS[token.lower()])
        else:
            raise ValueError(f"cannot parse {token!r} from pairing {pairing!r}")
    if len(colors) != 2:
        raise ValueError(f"expected two colors in pairing {pairing!r}")
    return (colors[0], colors[1])

def parse_reference_rows(text: str) -> list[dict[str, str | float]]:
    rows: list[dict[str, str | float]] = []
    in_table = False
    for raw in text.splitlines():
        line = raw.strip()
        if line.startswith(REFERENCE_HEADER):
            in_table = True
            continue
        if not in_table:
            continue
        if not line.startswith("|"):
            break
        if line.startswith("|---"):
            continue
        cells = [cell.strip() for cell in line.strip("|").split("|")]
        if len(cells) != 4:
            continue
        pairing, ratio_str, normal, large = cells
        rows.append(
            {
                "pairing": pairing,
                "ratio": float(ratio_str),
                "normal": normal,
                "large": large,
            }
        )
    return rows

def run_css_mode(
    css_path: Path, page_bg_tok: str = "#ffffff", profile: str = "standard"
) -> tuple[int, str]:
    floors = FLOORS.get(profile.lower(), FLOORS["standard"])
    page_bg_raw = parse_color_extended(page_bg_tok)
    if page_bg_raw is None:
        raise ValueError(f"cannot parse --page-bg {page_bg_tok!r}")
    page_bg_rgb = composite(page_bg_raw, (255, 255, 255))

    try:
        css = css_path.read_text(encoding="utf-8", errors="replace")
    except OSError as e:
        raise ValueError(f"cannot read CSS file: {e}") from e

    seen: dict[str, str] = {}
    for tok in COLOR_RE.findall(css):
        c = parse_color_extended(tok)
        if c is not None:
            seen.setdefault(fmt_hex(composite(c, page_bg_rgb)), tok)
    colors = list(seen.items())

    lines = [
        (
            f"TRIAGE (not a verdict): {len(colors)} distinct colors in {css_path}; "
            f"pairs below the {profile} text floor ({floors['text']}:1) flagged."
        )
    ]
    flagged = 0
    for (hex1, _tok1), (hex2, _tok2) in itertools.combinations(colors, 2):
        r = contrast_ratio(parse_color(hex1), parse_color(hex2))
        if r < floors["text"]:
            flagged += 1
            band = (
                "below UI floor (3:1)"
                if r < floors["ui"]
                else "text fails, large/UI may pass"
            )
            lines.append(f"  {hex1} × {hex2}: {r:.2f}:1 — {band}")
    total_pairs = len(colors) * (len(colors) - 1) // 2 if len(colors) > 1 else 0
    lines.append(
        f"{flagged} pair(s) flagged out of {total_pairs}. "
        "A flagged pair only matters if the two colors actually meet in the page — verify intent, then fix or record."
    )
    return (0, "\n".join(lines))

def run_pair_mode(
    bg_tok: str, fg_toks: list[str], profile: str = "standard"
) -> tuple[int, str]:
    floors = FLOORS.get(profile.lower(), FLOORS["standard"])
    bg_raw = parse_color_extended(bg_tok)
    if bg_raw is None:
        raise ValueError(f"cannot parse background {bg_tok!r}")
    bg_rgb = composite(bg_raw, (255, 255, 255))

    lines = [f"profile: {profile} | background: {fmt_hex(bg_rgb)}"]
    failures = 0
    for tok in fg_toks:
        fg_raw = parse_color_extended(tok)
        if fg_raw is None:
            lines.append(f"  {tok}: UNPARSEABLE")
            failures += 1
            continue
        fg_rgb = composite(fg_raw, bg_rgb)
        r = contrast_ratio(fg_rgb, bg_rgb)
        verdicts = " | ".join(
            f"{use} {'PASS' if r >= floor else 'FAIL'} (>={floor}:1)"
            for use, floor in floors.items()
        )
        lines.append(f"  {fmt_hex(fg_rgb)} ({tok}): {r:.2f}:1 - {verdicts}")
        lines.append(
            f"    -> REPORT.md: | [use] | {fmt_hex(fg_rgb)} | {fmt_hex(bg_rgb)} | {r:.2f}:1 | "
            f"{floors['text']}:1 | {'PASS' if r >= floors['text'] else 'FAIL'} |"
        )
        if r < floors["text"]:
            failures += 1
    return (1 if failures else 0, "\n".join(lines))

def contrast(
    color_a: str | None = typer.Argument(
        None, help="First color as hex or named color (black/white)."
    ),
    color_b: str | None = typer.Argument(
        None, help="Second color as hex or named color (black/white)."
    ),
    bg: str | None = typer.Option(None, "--bg", help="Background color for pair mode."),
    fg: list[str] = typer.Option(  # noqa: B008
        [], "--fg", help="Foreground color(s) for pair mode."
    ),
    profile: str = typer.Option(
        "standard",
        "--profile",
        help="Compliance profile: 'standard' (AA) or 'shield' (AAA).",
    ),
    css: str | None = typer.Option(
        None, "--css", help="CSS file path to triage color literals."
    ),
    page_bg: str = typer.Option(
        "#ffffff", "--page-bg", help="Page background for CSS alpha compositing."
    ),
    selftest: bool = typer.Option(
        False, "--selftest", help="Run self-test against the reference table."
    ),
    self_test_flag: bool = typer.Option(
        False, "--self-test", help="Run self-test (alias)."
    ),
) -> None:
    """Check WCAG 2.x contrast ratio between colors, in pairs, or triage CSS."""
    if selftest or self_test_flag:
        code, msg = contrast_selftest()
        if code == 0:
            console.print(msg)
        else:
            err_console.print(msg)
        raise typer.Exit(code=code)

    if css:
        try:
            code, msg = run_css_mode(
                Path(css).resolve(), page_bg_tok=page_bg, profile=profile
            )
            console.print(msg)
            raise typer.Exit(code=code)
        except ValueError as exc:
            err_console.print(f"error: {exc}")
            raise typer.Exit(code=2)

    if bg:
        fg_list = list(fg)
        if color_a:
            fg_list.insert(0, color_a)
        if color_b:
            fg_list.append(color_b)
        if not fg_list:
            err_console.print(
                "error: pair mode needs at least one foreground color (--fg)"
            )
            raise typer.Exit(code=2)
        try:
            code, msg = run_pair_mode(bg, fg_list, profile=profile)
            console.print(msg)
            raise typer.Exit(code=code)
        except ValueError as exc:
            err_console.print(f"error: {exc}")
            raise typer.Exit(code=2)

    if color_a is None or color_b is None:
        err_console.print(
            "usage: buddhi scripts contrast <hex1> <hex2> | --bg <bg> --fg <fg>... | --css <file> | --selftest"
        )
        raise typer.Exit(code=2)

    try:
        result = run_contrast_check(color_a, color_b, profile=profile)
    except ValueError as exc:
        err_console.print(f"error: {exc}")
        raise typer.Exit(code=2)

    console.print(result.formatted_text)
    raise typer.Exit(code=result.exit_code)

def execute_check_contrast(
    color_a: str | None = None,
    color_b: str | None = None,
    bg: str | None = None,
    fg: Any = None,
    profile: str = "standard",
    css_path: str | None = None,
    page_bg: str = "#ffffff",
) -> str:
    """Check contrast ratio between colors or across stylesheets."""
    try:
        if css_path:
            p = Path(css_path)
            if not p.is_file():
                return f"Error: CSS file not found: {css_path}"
            _code, msg = run_css_mode(p, page_bg_tok=page_bg, profile=profile)
            return msg

        if bg:
            fg_list: list[str] = []
            if isinstance(fg, list):
                fg_list.extend(str(item) for item in fg)
            elif isinstance(fg, str):
                fg_list.append(fg)
            if color_a:
                fg_list.insert(0, color_a)
            if color_b:
                fg_list.append(color_b)
            if not fg_list:
                return "Error: pair mode needs at least one foreground color (fg)"
            _code, msg = run_pair_mode(bg, fg_list, profile=profile)
            return msg

        if color_a is not None and color_b is not None:
            res = run_contrast_check(color_a, color_b, profile=profile)
            return res.formatted_text

        return "Error: supply either (color_a, color_b), (bg, fg), or css_path"
    except Exception as exc:  # noqa: BLE001
        return f"Error checking contrast: {exc}"

def selftest() -> tuple[int, str]:
    text = _get_skill_doc_text()
    if text is None:
        return (
            2,
            "selftest: antislop-human/SKILL.md reference doc not found; cannot check table",
        )

    try:
        rows = parse_reference_rows(text)
    except Exception as exc:  # noqa: BLE001
        return 1, f"selftest: could not read table from SKILL.md: {exc}"

    if not rows:
        return 1, "selftest: no reference rows found in SKILL.md"

    failures = []
    for row in rows:
        pairing_str = str(row["pairing"])
        color_a, color_b = parse_pairing(pairing_str)
        raw = contrast_ratio(color_a, color_b)
        computed = round(raw, 2)
        expected_normal = "Pass" if raw >= 4.5 else "Fail"
        expected_large = "Pass" if raw >= 3.0 else "Fail"

        if f"{computed:.2f}" != f"{float(row['ratio']):.2f}":
            failures.append(
                f"selftest: {pairing_str}: table says {row['ratio']}, formula says {computed:.2f}"
            )
        if row["normal"] != expected_normal:
            failures.append(
                f"selftest: {pairing_str}: normal text marked {row['normal']}, should be {expected_normal}"
            )
        if row["large"] != expected_large:
            failures.append(
                f"selftest: {pairing_str}: large text marked {row['large']}, should be {expected_large}"
            )

    upstream_cases = [
        ("#767676", "#5a5a5a", False),
        ("#121212", "#f2f2f2", True),
        ("#ffffff", "#747474", True),
        ("#ffffff", "#777777", False),
        ("hsl(14, 60%, 72%)", "#121212", True),
        ("rgba(0,0,0,0.5)", "white", False),
    ]
    for bg_tok, fg_tok, should_pass in upstream_cases:
        bg_ext = parse_color_extended(bg_tok)
        fg_ext = parse_color_extended(fg_tok)
        if bg_ext is None or fg_ext is None:
            failures.append(
                f"selftest: could not parse upstream case {bg_tok} vs {fg_tok}"
            )
            continue
        bg_rgb = composite(bg_ext, (255, 255, 255))
        fg_rgb = composite(fg_ext, bg_rgb)
        r = contrast_ratio(fg_rgb, bg_rgb)
        if (r >= 4.5) != should_pass:
            failures.append(
                f"selftest upstream: {bg_tok} vs {fg_tok}: {r:.2f}:1 -> {'pass' if r >= 4.5 else 'fail'} (expected {'pass' if should_pass else 'fail'})"
            )

    if failures:
        return 1, "\n".join(failures)
    return (
        0,
        f"selftest: {len(rows)} reference pairs and {len(upstream_cases)} upstream cases OK",
    )

def looks_like_argument(token: str) -> bool:
    if token.startswith("-"):
        return True
    if "/" in token or "\\" in token:
        return True
    if re.search(r"\.\w{1,6}$", token):
        return True
    if "=" in token:
        return True
    if token.startswith(("'", '"')) or "%[" in token or "{" in token:
        return True
    if re.match(r"^\w+:$", token):
        return True
    return bool(token.startswith(("$", "@", "#")))

def is_invocation(line: str) -> bool:
    stripped = re.sub(r"^\s*[$>]\s+", "", line).strip()
    if not stripped:
        return False
    tokens = stripped.split()
    head = os.path.basename(tokens[0])
    runnable = (
        head in TOOLS
        or tokens[0].startswith(("./", "../", "/"))
        or bool(re.match(r"^\w[\w.-]*\.(?:mjs|js|py|sh)$", head))
    )
    if not runnable:
        return False
    return any(looks_like_argument(t) for t in tokens[1:])

def parse_receipt_lines(lines: list[str]) -> list[bool]:
    """Flag which lines belong to a fenced block, indented code, or shell transcript."""
    in_receipt = [False] * len(lines)
    fence: str | None = None
    transcript = False

    for i, line in enumerate(lines):
        fence_match = re.match(r"^\s*(`{3,}|~{3,})", line)
        if fence_match:
            if fence is None:
                fence = fence_match.group(1)[:3]
                in_receipt[i] = True
                continue
            if fence_match.group(1).startswith(fence):
                fence = None
                in_receipt[i] = True
                continue
        if fence is not None:
            in_receipt[i] = True
            continue

        if re.match(r"^\s{4,}\S", line) and not re.match(r"^\s*[-*+]\s", line):
            in_receipt[i] = True
            continue

        if re.match(r"^\s*\$\s+\S", line):
            in_receipt[i] = True
            transcript = True
            continue
        if transcript:
            if not line.strip():
                transcript = False
            else:
                in_receipt[i] = True

    return in_receipt

def extract_receipt_runs(lines: list[str]) -> list[ReceiptRun]:
    """Group contiguous receipt lines into runs and collect command and outputs."""
    in_receipt = parse_receipt_lines(lines)
    runs: list[ReceiptRun] = []
    i = 0
    n = len(lines)

    while i < n:
        if not in_receipt[i]:
            i += 1
            continue
        start = i
        while i < n and in_receipt[i]:
            i += 1
        end = i

        block_lines = lines[start:end]
        inv_idx = -1
        for idx, bline in enumerate(block_lines):
            if is_invocation(bline):
                inv_idx = idx
                break

        if inv_idx != -1 and inv_idx + 1 < len(block_lines):
            cmd = block_lines[inv_idx].strip()
            out_lines = [l for l in block_lines[inv_idx + 1 :] if not is_invocation(l)]
            if out_lines:
                run = ReceiptRun(
                    start_line=start, end_line=end, command=cmd, output_lines=out_lines
                )
                for ol in out_lines:
                    for m in NUMBER_RE.finditer(ol):
                        run.numbers.add(m.group(1))
                    for m in HEX_RE.finditer(ol):
                        run.hexes.add(m.group(1).lower())
                runs.append(run)

    return runs

def check_report(
    text: str,
    filepath: str = "<stdin>",
    base_dir: Path | None = None,
    window: int = 4,
) -> tuple[bool, list[Finding], list[str]]:
    """Validate report text and return (passed, findings, labeled_lines)."""
    lines = text.splitlines()
    in_receipt = parse_receipt_lines(lines)
    runs = extract_receipt_runs(lines)
    findings: list[Finding] = []
    base = base_dir or Path.cwd()

    # 1. Measurement claims check
    labeled_lines: list[str] = []
    prev_line = ""

    for i, line in enumerate(lines):
        unsupported_on_line: list[str] = []
        if not in_receipt[i]:
            hits = claims_in(line, i, prev_line)
            for hit in hits:
                # Find covering receipt run within window
                covered = False
                for r in runs:
                    if r.start_line - window - 1 <= i <= r.end_line + window + 1:
                        if hit.is_hex and hit.value in r.hexes:
                            covered = True
                            break
                        if not hit.is_hex and hit.value in r.numbers:
                            covered = True
                            break
                if not covered:
                    findings.append(
                        Finding(
                            file=filepath,
                            line=i + 1,
