def collapse_blank_lines(lines: list[str]) -> list[str]:
    """Collapse consecutive blank/whitespace-only lines to a single blank line."""
    result: list[str] = []
    prev_blank = False
    for line in lines:
        is_blank = not line.strip()
        if is_blank:
            if not prev_blank:
                result.append("")
                prev_blank = True
        else:
            result.append(line)
            prev_blank = False
    return result

def collapse_duplicate_lines(lines: list[str]) -> list[str]:
    """Collapse consecutive identical lines into a single line with a repeat indicator."""
    if not lines:
        return []

    result: list[str] = []
    current_line = lines[0]
    count = 1

    for line in lines[1:]:
        if line == current_line and line.strip() != "":
            count += 1
        else:
            if count > 1:
                result.append(f"{current_line} [repeated {count} times]")
            else:
                result.append(current_line)
            current_line = line
            count = 1

    if count > 1:
        result.append(f"{current_line} [repeated {count} times]")
    else:
        result.append(current_line)

    return result

