def extract_command_from_payload(payload: Any) -> tuple[str | None, str | None]:
    """Extract command string and key path from Antigravity tool payload.

    Returns:
        (command_str, field_key) or (None, None)
    """
    if not isinstance(payload, dict):
        return None, None

    # Pattern 1: {"toolCall": {"name": "run_command", "args": {"CommandLine": "..."}}}
    tool_call = payload.get("toolCall") or payload.get("tool_call")
    if isinstance(tool_call, dict):
        tool_name = tool_call.get("name", "")
        if tool_name in ("run_command", "terminal", "bash", "execute_command"):
            args = tool_call.get("args") or tool_call.get("parameters") or {}
            if isinstance(args, dict):
                for key in ("CommandLine", "command", "cmd"):
                    if key in args and isinstance(args[key], str):
                        return args[key], f"toolCall.args.{key}"

    # Pattern 2: {"command": "..."} or {"CommandLine": "..."}
    for key in ("CommandLine", "command", "cmd"):
        val = payload.get(key)
        if isinstance(val, str):
            return val, key

    # Pattern 3: Nested input/parameters
    for outer in ("input", "tool_input", "parameters"):
        inner = payload.get(outer)
        if isinstance(inner, dict):
            for key in ("CommandLine", "command", "cmd"):
                val = inner.get(key)
                if isinstance(val, str):
                    return val, f"{outer}.{key}"

    return None, None

def is_already_wrapped(command: str) -> bool:
    """Check if the command is already invoked through rtk."""
    return bool(ALREADY_WRAPPED_REGEX.search(command.strip()))

def is_compound_or_redirect(command: str) -> bool:
    """Check if the command includes pipes, redirections, or sequence operators."""
    return bool(COMPOUND_REGEX.search(command))

def evaluate_rewrite(command: str) -> RewriteDecision:
    """Evaluate whether to rewrite the command for token savings."""
    stripped = command.strip()

    if not stripped:
        return RewriteDecision(
            action="skip",
            reason="empty_command",
            original_command=command,
            rewritten_command=command,
        )

    # Disable switch via env var
    if (
        os.environ.get("BUDDHI_RTK_DISABLE_REWRITE") == "1"
        or os.environ.get("BUDDHI_RTK_ACTIVE") == "1"
    ):
        return RewriteDecision(
            action="skip",
            reason="disabled_by_env",
            original_command=command,
            rewritten_command=command,
        )

    if is_already_wrapped(stripped):
        return RewriteDecision(
            action="skip",
            reason="already_wrapped",
            original_command=command,
            rewritten_command=command,
        )

    if is_compound_or_redirect(stripped):
        return RewriteDecision(
            action="skip",
            reason="compound_or_pipe",
            original_command=command,
            rewritten_command=command,
        )

    if not is_rewrite_candidate(stripped):
        return RewriteDecision(
            action="skip",
            reason="no_rewrite_candidate",
            original_command=command,
            rewritten_command=command,
        )

    rewritten = f"buddhi scripts rtk run -- {stripped}"
    return RewriteDecision(
        action="rewrite",
        reason="token_filter_candidate",
        original_command=command,
        rewritten_command=rewritten,
    )

def rtk_rewrite_cmd(
    ctx: typer.Context,
    json_mode: bool = typer.Option(
        False, "--json", help="Output rewrite decision as JSON."
    ),
) -> None:
    """Evaluate whether a command would be rewritten by the RTK hook."""
    from buddhi.scripts.rtk.rewrite import evaluate_rewrite

    cmd_args = ctx.args
    if not cmd_args:
        err_console.print("[red]error:[/red] no command specified to evaluate.")
        raise typer.Exit(code=1)

    cmd_str = " ".join(cmd_args)
    decision = evaluate_rewrite(cmd_str)

    if json_mode:
        import json

        data = {
            "action": decision.action,
            "reason": decision.reason,
            "original": decision.original_command,
            "rewritten": decision.rewritten_command,
        }
        console.print(json.dumps(data, indent=2), markup=False, highlight=False)
    else:
        if decision.action == "rewrite":
            console.print(decision.rewritten_command)
        else:
            console.print(f"[dim]no rewrite ({decision.reason}): {cmd_str}[/dim]")

    if decision.action != "rewrite":
        raise typer.Exit(code=1)

def handle_hook_payload(payload: Any) -> dict[str, Any]:
    """Process an Antigravity PreToolUse hook payload and return overwrite or empty dict."""
    try:
        command, field_path = extract_command_from_payload(payload)
        if not command:
            return {}

        decision = evaluate_rewrite(command)
        if decision.action != "rewrite":
            return {}

        # Construct Antigravity overwrite structure
        # If field was CommandLine inside toolCall.args
        if field_path == "toolCall.args.CommandLine":
            return {"overwrite": {"CommandLine": decision.rewritten_command}}
        elif field_path == "toolCall.args.command":
            return {"overwrite": {"command": decision.rewritten_command}}
        else:
            return {
                "overwrite": {
                    "CommandLine": decision.rewritten_command,
                    "command": decision.rewritten_command,
                }
            }

    except Exception as err:  # noqa: BLE001
        logger.warning("Error in RTK hook handler: %s", err)
        return {}

def estimate_tokens(text: str) -> int:
    """Fast, dependency-free token estimator (4 characters per token)."""
    return max(1, (len(text) + 3) // 4) if text else 0

def sanitize_filename(name: str) -> str:
    """Convert command name into a safe filesystem string."""
    return re.sub(r"[^\w\-.]+", "_", name).strip("_")[:40]

def save_raw_failure_log(cmd_name: str, raw_content: str, raw_dir: Path) -> Path:
    """Save raw command failure output and prune older logs if needed."""
    raw_dir.mkdir(parents=True, exist_ok=True)

    timestamp = int(time.time())
    safe_slug = sanitize_filename(cmd_name)
    log_file = raw_dir / f"{timestamp}_{safe_slug}.log"

    try:
        log_file.write_text(raw_content, encoding="utf-8", errors="replace")
    except Exception as err:  # noqa: BLE001
        logger.warning("Failed to write failure recovery log to %s: %s", log_file, err)

    # Prune old logs to avoid unbounded directory growth
    try:
        existing = sorted(raw_dir.glob("*.log"), key=lambda p: p.stat().st_mtime)
        if len(existing) > MAX_RAW_LOGS:
            for p in existing[:-MAX_RAW_LOGS]:
                try:
                    p.unlink(missing_ok=True)
                except OSError:
                    pass
    except Exception:  # noqa: BLE001, S110
        pass

    return log_file

def redact_command_line(command: str) -> str:
    """Retain command binary and safe subcommands while redacting parameters and secrets."""
    stripped = command.strip()
    try:
        parts = shlex.split(stripped, posix=False)
    except Exception:  # noqa: BLE001
        parts = stripped.split()

    if not parts:
        return ""

    prog = os.path.basename(parts[0]).lower()
    if prog.endswith((".exe", ".cmd", ".bat")):
        prog = prog.rsplit(".", 1)[0]

    safe_parts: list[str] = [parts[0]]

    if len(parts) > 1:
        sub = parts[1].lower()
        if prog in SAFE_SUBCOMMANDS and sub in SAFE_SUBCOMMANDS[prog]:
            safe_parts.append(parts[1])
            if len(parts) > 2:
                safe_parts.append("[args redacted]")
        else:
            safe_parts.append("[args redacted]")

    return " ".join(safe_parts)

def rtk_run_cmd(
    ctx: typer.Context,
    raw: bool = typer.Option(
        False, "--raw", help="Bypass filtering and print raw output."
    ),
    generic: bool = typer.Option(
        False, "--generic", help="Force generic fallback filter."
    ),
) -> None:
    """Execute a command, compress output to save LLM tokens, and preserve exit code."""
    from buddhi.scripts.rtk.runner import run_command_filtered

    cmd_args = ctx.args
    if not cmd_args:
        err_console.print(
            "[red]error:[/red] no command specified to execute. Use: buddhi scripts rtk run -- <command>"
        )
        raise typer.Exit(code=1)

    result = run_command_filtered(
        cmd_args=cmd_args,
        force_generic=generic,
    )

    if raw:
        output = result.raw_output
    else:
        output = result.filtered_output

    if output:
        sys.stdout.write(output)
        if not output.endswith("\n"):
            sys.stdout.write("\n")
        sys.stdout.flush()

    if result.exit_code != 0 and result.raw_log_path:
        typer.echo(f"[rtk: full raw output saved to {result.raw_log_path}]", err=True)

    raise typer.Exit(code=result.exit_code)

def compute_filter_hash(path: Path) -> str:
    """Compute the SHA-256 hash of a filter file."""
    content = path.read_bytes()
    return hashlib.sha256(content).hexdigest()

def get_trusted_hashes(trust_store: Path = DEFAULT_TRUST_STORE) -> dict[str, str]:
    """Load the map of trusted filter filenames to SHA-256 hashes."""
    if not trust_store.is_file():
        return {}
    try:
        data = json.loads(trust_store.read_text(encoding="utf-8"))
        if isinstance(data, dict):
            return {k: str(v) for k, v in data.items()}
    except Exception as err:  # noqa: BLE001
        logger.warning("Failed to read trust store from %s: %s", trust_store, err)
    return {}

def is_filter_trusted(path: Path, trust_store: Path = DEFAULT_TRUST_STORE) -> bool:
    """Check if the given filter file matches its trusted SHA-256 hash."""
    if not path.is_file():
        return False
    trusted = get_trusted_hashes(trust_store)
    file_name = path.name
    if file_name not in trusted:
        return False
    current_hash = compute_filter_hash(path)
    return current_hash == trusted[file_name]

