def install_skill(
    entry: SkillRegistryEntry,
    project_root: Path,
    force: bool = False,
) -> SkillInstallReport:
    """Install a custom skill template into `<project_root>/.agents/skills/<target_dir_name>`.

    If the destination directory already exists and `force` is False, the installation
    is skipped with a warning report. If `force` is True, existing files are overwritten.
    """
    root = project_root.resolve()
    target_skill_dir = root / ".agents" / "skills" / entry.target_dir_name

    report = SkillInstallReport(
        skill_name=entry.name,
        target_dir=target_skill_dir,
    )

    if target_skill_dir.exists():
        if not force:
            report.skipped = True
            return report
        report.overwritten = True

    try:
        template_root = resources.files(entry.template_pkg)
        with resources.as_file(template_root) as src_dir:
            if not src_dir.is_dir():
                raise BuddhiFsError(
                    f"Template directory missing for skill '{entry.name}': {src_dir}"
                )

            target_skill_dir.mkdir(parents=True, exist_ok=True)

            for src_path in sorted(src_dir.rglob("*")):
                if src_path.is_dir():
                    continue
                if "__pycache__" in src_path.parts:
                    continue
                if src_path.suffix in (".pyc", ".pyo"):
                    continue
                if src_path.name == "__init__.py":
                    # __init__.py exists only for packaging purposes; do not scaffold into skill
                    continue

                rel = src_path.relative_to(src_dir)
                dest_path = target_skill_dir / rel
                dest_path.parent.mkdir(parents=True, exist_ok=True)
                shutil.copyfile(src_path, dest_path)
                report.created.append(dest_path)

    except (OSError, ModuleNotFoundError, FileNotFoundError) as exc:
        raise BuddhiFsError(
            f"Failed installing skill '{entry.name}' to {target_skill_dir}: {exc}"
        ) from exc

    return report

def get_skill(name: str) -> SkillRegistryEntry | None:
    """Retrieve a skill entry by name or flag (e.g. 'repo-to-skill' or '--repo-to-skill')."""
    if name in _SKILL_REGISTRY:
        return _SKILL_REGISTRY[name]
    for entry in _SKILL_REGISTRY.values():
        if entry.flag == name or entry.flag.lstrip("-") == name.lstrip("-"):
            return entry
    return None

def run_skill(
    skill_name: str = typer.Argument(
        ..., help="Name of the skill (e.g. 'repo-to-skill')."
    ),
    target: str = typer.Argument(..., help="Target repository path or URL."),
    json_mode: bool = typer.Option(
        False, "--json", help="Emit structured output in JSON format."
    ),
) -> None:
    """Execute helper scripts associated with a custom agent skill."""
    entry = get_skill(skill_name)
    if entry is None:
        err_console.print(f"[red]error:[/red] unknown skill: '{skill_name}'")
        raise typer.Exit(code=1)

    try:
        exit_code = entry.execute_runner(target, json_mode=json_mode)
        if exit_code != 0:
            raise typer.Exit(code=exit_code)
    except Exception as exc:
        err_console.print(
            f"[red]error:[/red] execution failed for skill '{skill_name}': {exc}"
        )
        raise typer.Exit(code=1) from exc

def list_skills() -> list[SkillRegistryEntry]:
    """List all registered custom skills."""
    return list(_SKILL_REGISTRY.values())

