def __init__(self, limit: int = 200) -> None:
        self.limit = limit
        self.used_slugs_lower: set[str] = {"index"}
        self.label_to_slug: dict[str, str] = {}

def get(self, label: str, default: str | None = None) -> str | None:
        """Get the registered slug for a label."""
        return self.label_to_slug.get(label, default)

class SlugResolver:
    """Two-pass unique slug assigner with case-insensitive collision handling."""

    def __init__(self, limit: int = 200) -> None:
        self.limit = limit
        self.used_slugs_lower: set[str] = {"index"}
        self.label_to_slug: dict[str, str] = {}

    def register(self, label: str) -> str:
        """Register a label and assign it a unique case-deduplicated slug."""
        if label in self.label_to_slug:
            return self.label_to_slug[label]

        base = safe_filename(label, self.limit)
        slug = base
        n = 2
        while slug.lower() in self.used_slugs_lower:
            slug = f"{base}_{n}"
            n += 1

        self.used_slugs_lower.add(slug.lower())
        self.label_to_slug[label] = slug
        return slug

    def get(self, label: str, default: str | None = None) -> str | None:
        """Get the registered slug for a label."""
        return self.label_to_slug.get(label, default)

def dfs(node: str) -> None:
        if len(cycles) >= max_cycles:
            return
        visited.add(node)
        stack.append(node)
        on_stack.add(node)

        for neighbor in adj.get(node, []):
            if neighbor in on_stack:
                idx = stack.index(neighbor)
                cycle = stack[idx:] + [neighbor]
                cycles.append([c.removeprefix("file:") for c in cycle])
                if len(cycles) >= max_cycles:
                    return
            elif neighbor not in visited:
                dfs(neighbor)

        stack.pop()
        on_stack.remove(node)

def find_import_cycles(
    conn: sqlite3.Connection, max_cycles: int = 50
) -> list[list[str]]:
    """Detect circular file-level IMPORTS chains."""
    cur = conn.cursor()
    cur.execute(
        "SELECT source_id, target_id FROM edges WHERE kind = 'imports' AND resolved = 1"
    )
    adj: dict[str, list[str]] = collections.defaultdict(list)
    for src, tgt in cur.fetchall():
        if src.startswith("file:") and tgt.startswith("file:"):
            adj[src].append(tgt)

    cycles: list[list[str]] = []
    visited: set[str] = set()
    stack: list[str] = []
    on_stack: set[str] = set()

    def dfs(node: str) -> None:
        if len(cycles) >= max_cycles:
            return
        visited.add(node)
        stack.append(node)
        on_stack.add(node)

        for neighbor in adj.get(node, []):
            if neighbor in on_stack:
                idx = stack.index(neighbor)
                cycle = stack[idx:] + [neighbor]
                cycles.append([c.removeprefix("file:") for c in cycle])
                if len(cycles) >= max_cycles:
                    return
            elif neighbor not in visited:
                dfs(neighbor)

        stack.pop()
        on_stack.remove(node)

    for n in sorted(adj.keys()):
        if n not in visited:
            dfs(n)

    return cycles

