def resolve_symbol(q: str) -> tuple[str | None, list[str]]:
        cur = conn.cursor()
        cur.execute(
            "SELECT id, name, file_path FROM nodes WHERE id = ? OR name = ? OR qualified_name = ?",
            (q, q, q),
        )
        rows = cur.fetchall()
        if not rows:
            cur.execute(
                "SELECT id, name, file_path FROM nodes WHERE name LIKE ? LIMIT 5",
                (f"%{q}%",),
            )
            rows = cur.fetchall()
        if len(rows) == 1:
            return rows[0][0], []
        if len(rows) > 1:
            return None, [f"{r[0]} ({r[2]})" for r in rows]
        return None, []

def find_shortest_path(
    conn: sqlite3.Connection, source_query: str, target_query: str, max_hops: int = 8
) -> dict[str, Any]:
    """Find the shortest relational path between two symbols with candidate disambiguation."""

    def resolve_symbol(q: str) -> tuple[str | None, list[str]]:
        cur = conn.cursor()
        cur.execute(
            "SELECT id, name, file_path FROM nodes WHERE id = ? OR name = ? OR qualified_name = ?",
            (q, q, q),
        )
        rows = cur.fetchall()
        if not rows:
            cur.execute(
                "SELECT id, name, file_path FROM nodes WHERE name LIKE ? LIMIT 5",
                (f"%{q}%",),
            )
            rows = cur.fetchall()
        if len(rows) == 1:
            return rows[0][0], []
        if len(rows) > 1:
            return None, [f"{r[0]} ({r[2]})" for r in rows]
        return None, []

    s_id, s_disambig = resolve_symbol(source_query)
    t_id, t_disambig = resolve_symbol(target_query)

    if s_disambig:
        return {"error": "source_disambiguation_required", "candidates": s_disambig}
    if t_disambig:
        return {"error": "target_disambiguation_required", "candidates": t_disambig}
    if not s_id or not t_id:
        return {
            "error": "symbol_not_found",
            "source": s_id or source_query,
            "target": t_id or target_query,
        }

    # BFS
    queue = collections.deque([(s_id, [s_id])])
    visited = {s_id}

    while queue:
        curr, path = queue.popleft()
        if curr == t_id:
            return {"found": True, "hops": len(path) - 1, "path": path}
        if len(path) - 1 >= max_hops:
            continue

        cur = conn.cursor()
        cur.execute(
            "SELECT target_id FROM edges WHERE source_id = ? AND kind IN ('calls', 'inherits', 'imports') AND resolved = 1",
            (curr,),
        )
        for (nxt,) in cur.fetchall():
            if nxt not in visited:
                visited.add(nxt)
                queue.append((nxt, path + [nxt]))

    return {"found": False, "hops": -1, "path": []}

def execute_buddhi_graph(
    action: str,
    db_path: str,
    root_path: Path | None = None,
    targets: list[str] | None = None,
    git_ref: str | None = None,
    staged: bool = False,
    source: str | None = None,
    target: str | None = None,
    community_id: int | None = None,
    max_hops: int = 3,
    top_n: int = 10,
    as_json: bool = False,
) -> str:
    """Execute action on CodeGraph SQLite database."""
    p = Path(db_path)
    if not p.is_file():
        err_payload = {
            "error": "graph_not_found",
            "hint": "Run `buddhi generate` or `buddhi init` to generate the code graph first.",
        }
        return (
            json.dumps(err_payload, indent=2)
            if as_json
            else f"Error: Code graph database not found at {db_path}. Run `buddhi generate` first."
        )

    root = root_path or Path.cwd()
    conn = sqlite3.connect(f"file:{p.resolve().as_posix()}?mode=ro", uri=True)

    try:
        if action == "blast_radius":
            report = compute_blast_radius(
                conn,
                targets=targets,
                git_ref=git_ref,
                staged=staged,
                max_hops=max_hops,
                root_path=root,
            )
            payload = {
                "risk_level": report.risk_level,
                "target_files": report.target_files,
                "target_nodes_count": len(report.target_nodes),
                "direct_callers_count": len(report.direct_callers),
                "direct_callers": report.direct_callers[:20],
                "transitive_callers_count": len(report.transitive_callers),
                "transitive_callers": report.transitive_callers[:20],
                "affected_communities": report.affected_communities,
                "impacted_god_nodes": report.impacted_god_nodes,
                "crossed_bridges_count": len(report.crossed_bridges),
                "import_cycles_involving_targets": report.new_import_cycles,
            }
            if as_json:
                return json.dumps(payload, indent=2)
            md = [
                f"# Blast Radius Report (Risk: **{report.risk_level.upper()}**)",
