def plan(
    path: Path = typer.Argument(Path("."), help="Root directory to scan."),  # noqa: B008
    max_file_size: int = typer.Option(
        2_000_000, "--max-file-size", help="Skip files larger than this, in bytes."
    ),
    verbose: bool = typer.Option(
        False, "-v", "--verbose", help="Print per-file warnings."
    ),
) -> None:
    """Compute a bottom-up, staleness-aware doc-generation plan and write docs-plan.json."""
    root = path.resolve()

    if not root.exists():
        err_console.print(f"[red]error:[/red] path does not exist: {root}")
        raise typer.Exit(code=1)
    if not root.is_dir():
        err_console.print(f"[red]error:[/red] not a directory: {root}")
        raise typer.Exit(code=1)

    try:
        ensure_buddhi_dirs(root)
        ensure_docs_dir(root)
        ensure_site_dir(root)
    except BuddhiFsError as exc:
        err_console.print(f"[red]error:[/red] {exc}")
        raise typer.Exit(code=1) from exc

    result = run_pipeline(root, max_file_size=max_file_size)
    if verbose:
        for warning in result.build_ctx.warnings:
            err_console.print(f"[yellow]warning:[/yellow] {warning}")

    entries = build_docs_plan(result.build_ctx.graph, root)
    plan_path = root / ".buddhi" / "docs-plan.json"
    try:
        plan_path.write_text(
            json.dumps(plan_to_json(entries), indent=2), encoding="utf-8"
        )
    except OSError as exc:
        err_console.print(f"[red]error:[/red] failed writing {plan_path}: {exc}")
        raise typer.Exit(code=1) from exc

    stale = sum(1 for e in entries if e.needs_generation)
    console.print(f"[bold green]done[/bold green] planned docs for {root}")
    console.print(f"  entries: {len(entries)} total, {stale} need (re)generation")
    console.print(f"  wrote: {plan_path}")

def generate(
    path: Path = typer.Argument(Path("."), help="Root directory to scan."),  # noqa: B008
    tree: bool = typer.Option(
        True,
        "--tree/--no-tree",
        help="Reserved for interface stability; graph generation is always full "
        "(JSON + SQLite + HTML are always produced).",
    ),
    max_file_size: int = typer.Option(
        2_000_000, "--max-file-size", help="Skip files larger than this, in bytes."
    ),
    verbose: bool = typer.Option(
        False, "-v", "--verbose", help="Print per-file warnings."
    ),
) -> None:
    """Scan PATH, build a code graph, and write it to .buddhi/graphs/."""
    root = path.resolve()

    if not root.exists():
        err_console.print(f"[red]error:[/red] path does not exist: {root}")
        raise typer.Exit(code=1)
    if not root.is_dir():
        err_console.print(f"[red]error:[/red] not a directory: {root}")
        raise typer.Exit(code=1)

    result = run_pipeline(root, max_file_size=max_file_size)
    walk_result = result.walk_result
    build_ctx = result.build_ctx

    if verbose:
        for lang, err in result.language_warnings.items():
            err_console.print(
                f"[yellow]warning:[/yellow] language '{lang}' unavailable: {err}"
            )

    if not walk_result.files:
        console.print(
            "[yellow]warning:[/yellow] no supported source files found under this path."
        )

    if verbose:
        for warning in build_ctx.warnings:
            err_console.print(f"[yellow]warning:[/yellow] {warning}")

    try:
        graphs_dir = ensure_buddhi_dirs(root)
    except BuddhiFsError as exc:
        err_console.print(f"[red]error:[/red] {exc}")
        raise typer.Exit(code=1) from exc

    json_path = graphs_dir / "tree-graph.json"
    db_path = graphs_dir / "tree-graph.db"
    html_path = graphs_dir / "tree-graph.html"

    try:
        write_json(build_ctx.graph, json_path)
        write_sqlite(
            build_ctx.graph,
            db_path,
            root_path=str(root),
            extract_cache_entries=build_ctx.extract_cache_entries,
        )
        write_html(build_ctx.graph, html_path, root_label=root.name or str(root))
    except OSError as exc:
        err_console.print(f"[red]error:[/red] failed writing artifacts: {exc}")
        raise typer.Exit(code=1) from exc

    symbols = get_symbols(console)
    languages_seen = sorted({f.language for f in walk_result.files})
    console.print(f"{symbols['ok']} [bold white]Scanned {root}[/bold white]")
    cache_hits = build_ctx.stats.get("cache_hits", 0)
    console.print(
        f"  {symbols['bullet']} files: {build_ctx.stats.get('files_parsed', 0)} parsed ({cache_hits} cached), "
        f"{build_ctx.stats.get('files_failed', 0)} failed, "
        f"{len(walk_result.skipped_too_large)} skipped (too large)"
    )
    console.print(
        f"  {symbols['bullet']} languages: {', '.join(languages_seen) if languages_seen else '(none)'}"
    )
    console.print(
        f"  {symbols['bullet']} graph: {len(build_ctx.graph.nodes)} nodes, {len(build_ctx.graph.edges)} edges, "
        f"{result.community_count} communities"
    )
    console.print(f"  {symbols['bullet']} wrote: {json_path}")
    console.print(f"  {symbols['bullet']} wrote: {db_path}")
    console.print(f"  {symbols['bullet']} wrote: {html_path}")

    if walk_result.skipped_unsupported_grammar:
        for lang, count in walk_result.skipped_unsupported_grammar.items():
            console.print(
                f"  [yellow]skipped {count} .{lang} file(s): grammar unavailable[/yellow]"
            )

