def handle_session_start(root: Path, payload: dict) -> dict:
    """Handle SessionStart event: run lifecycle evaluation and inject skill recall index."""
    from buddhi.scripts.autoharness.layer import (
        resolve_autoharness_dir,
        resolve_skills_dir,
    )
    from buddhi.scripts.autoharness.lifecycle import evaluate_lifecycle
    from buddhi.scripts.autoharness.sidecar import is_agent_created, read_sidecar
    from buddhi.scripts.autoharness.skill_store import archive_skill
    from buddhi.scripts.autoharness.validate import parse_frontmatter

    skills_dir = resolve_skills_dir("project", root)
    if not skills_dir.is_dir():
        return {}

    # Read active agent skills
    agent_skills = {}
    for item in skills_dir.iterdir():
        if item.is_dir() and is_agent_created(item):
            sc = read_sidecar(item)
            if sc:
                agent_skills[item.name] = sc

    # Evaluate lifecycle
    decision = evaluate_lifecycle(
        agent_skills, current_request_count=100, layer="project"
    )
    for arch in decision.archive:
        try:
            archive_skill(skills_dir, arch)
        except OSError:
            pass

    # Build recall index
    categories: dict[str, list[str]] = {}
    for name in decision.keep:
        s_file = skills_dir / name / "SKILL.md"
        if s_file.is_file():
            try:
                fm, _ = parse_frontmatter(s_file.read_text(encoding="utf-8"))
                cat = fm.get("category", "general")
                desc = fm.get("description", "")[:60]
                categories.setdefault(cat, []).append(f"- {name} [project]: {desc}")
            except (OSError, ValueError):
                pass

    index_lines = ["[AutoHarness] Active Self-Learned Skills:"]
    for cat, items in sorted(categories.items()):
        index_lines.append(f"## {cat}")
        index_lines.extend(items)

    index_text = "\n".join(index_lines)

    # Consume last_run.json if present
    autoharness_dir = resolve_autoharness_dir("project", root)
    last_run_file = autoharness_dir / "last_run.json"
    last_run_summary = ""
    if last_run_file.is_file():
        try:
            data = json.loads(last_run_file.read_text(encoding="utf-8"))
            landed = len(data.get("landed", []))
            rejected = len(data.get("rejected", []))
            last_run_summary = f"[AutoHarness] Last promotion: landed {landed}, rejected {rejected} skills."
        except (OSError, json.JSONDecodeError):
            pass

    messages = []
    if last_run_summary:
        messages.append(last_run_summary)
    if len(categories) > 0:
        messages.append(index_text)

    if messages:
        return {
            "injectSteps": [{"systemMessage": {"systemMessage": "\n\n".join(messages)}}]
        }
    return {}

def handle_stop(root: Path, payload: dict) -> dict:
    """Handle Stop event: drain interactive intents and notify if thresholds reached."""
    from buddhi.scripts.autoharness.promoter import drain_and_promote

    try:
        drain_and_promote(layer="project", run_id="interactive", project_root=root)
    except (OSError, ValueError):
        pass

    return {}

def main() -> None:
    try:
        raw = sys.stdin.read(262144)
        payload = json.loads(raw) if raw.strip() else {}
    except (OSError, json.JSONDecodeError):
        payload = {}

    root = _resolve_project_root()
    res: dict = {}

    try:
        # Detect event type
        if (
            "conversationId" in payload
            and "toolCall" not in payload
            and "terminationReason" not in payload
        ):
            res = handle_session_start(root, payload)
        elif "toolCall" in payload:
            res = handle_pre_tool_use(root, payload)
        elif "terminationReason" in payload or "executionNum" in payload:
            res = handle_stop(root, payload)
        else:
            # Fallback
            res = {"decision": "allow"}
    except (OSError, ValueError):
        # Fail open
        res = {"decision": "allow"}

    print(json.dumps(res))

class FileViolation:
    path: str
    bytes: int
    before: int | None

    @property
    def tokens(self) -> int:
        return round(self.bytes / 4)

    @property
    def before_tokens(self) -> int | None:
        return round(self.before / 4) if self.before is not None else None

def check_staged_files(
    paths: list[str], max_tokens: int = 8000
) -> tuple[int, list[str]]:
    """Verify staged versions of paths against ratchet."""
    max_bytes = max_tokens * 4
    try:
        root = get_git_root()
    except (subprocess.CalledProcessError, OSError) as exc:
        return 2, [f"error: not a git repository: {exc}"]

    # Get renames from index
    renames: dict[str, str] = {}
    try:
        diff_out = run_git(["diff", "--cached", "--find-renames", "--name-status"])
        for line in diff_out.splitlines():
            parts = line.split("\t")
            if len(parts) >= 3 and parts[0].startswith("R"):
                renames[parts[2]] = parts[1]
    except (subprocess.CalledProcessError, OSError):
        pass

    normalized: list[str] = []
    for p in paths:
        try:
            rel = os.path.relpath(os.path.realpath(p), root)
        except (ValueError, OSError):
            rel = os.path.relpath(p, root)
        rel_posix = rel.replace("\\", "/")
        if is_source_file(rel_posix):
            normalized.append(rel_posix)

    unauthored = get_unauthored(normalized)
    eval_paths = [p for p in normalized if p not in unauthored]

    failures: list[FileViolation] = []
    for p in eval_paths:
        size = blob_bytes(f":{p}")
        if size is None or size <= max_bytes or is_ignored(f":{p}"):
            continue
        orig = renames.get(p, p)
        before = blob_bytes(f"HEAD:{orig}")
        if before is not None and size <= before:
            continue
        failures.append(FileViolation(path=p, bytes=size, before=before))

    if not failures:
        return 0, []

    lines = [
        f"Commit refused: source files over the budget of {format_tokens(max_bytes)} (bytes // 4)."
    ]
    for f in failures:
        frozen = f.before is not None and f.before > max_bytes
        limit: int = f.before if (frozen and f.before is not None) else max_bytes
        if frozen and f.before is not None:
            why = (
                f"already over budget at {format_tokens(f.before)}, so it may not grow"
            )
        elif f.before is None:
            why = "a new file, so it must fit the budget"
        else:
            why = f"was {format_tokens(f.before)}, so it must fit the budget"
        lines.append(f"  {f.path}: {format_tokens(f.bytes)}, {why}.")
        lines.append(f"    Cut at least {f.bytes - limit:,} bytes.")

    return 1, lines

def check_file_size_cmd(
    paths: list[str] = typer.Argument(None, help="Staged file paths to verify."),  # noqa: B008
    all_files: bool = typer.Option(
        False, "--all", help="Scan all tracked source files in git index."
    ),
    max_tokens: int = typer.Option(
        8000, "--max-tokens", help="Maximum tokens allowed per source file."
    ),
    selftest: bool = typer.Option(False, "--selftest", help="Run self-test."),
) -> None:
    """Check and ratchet source file sizes against token budget (bytes // 4)."""
    if selftest:
        code, msg = check_file_size_selftest()
        if code == 0:
            console.print(msg)
        else:
            err_console.print(msg)
        raise typer.Exit(code=code)

    if not all_files and not paths:
        err_console.print(
            "usage: buddhi scripts check-file-size --all [--max-tokens N] | <path>... | --selftest"
        )
        raise typer.Exit(code=2)

    if all_files:
        code, lines = check_all_files(max_tokens=max_tokens)
    else:
        code, lines = check_staged_files(paths, max_tokens=max_tokens)

    for line in lines:
        if code == 0:
            console.print(line)
        else:
            err_console.print(line)

    raise typer.Exit(code=code)

